INSERT INTO "sources" ("slug", "name", "type", "authorization_status", "terms_url", "notes") VALUES
  ('gem_board', 'Gem job boards', 'job_api', 'approved', 'https://help.gem.com/databases/gem-help-center/the-job-board-api', 'Open jobs of a company''s Gem board through the public Job Board API Gem documents for its customers'' boards (api.gem.com/job_board/v0/{board}/job_posts/), no key. jobs.gem.com has no robots.txt; api.gem.com answers its robots.txt with 403, which RFC 9309 reads as allowing. Boards are found on the careers pages we read; one request per board per run. Approved 2026-11-18 (Phase 0 review).'),
  ('rippling_board', 'Rippling job boards', 'job_page', 'approved', 'https://developer.rippling.com', 'Open jobs of a company''s Rippling board, read from its public board pages (ats.rippling.com/{board}/jobs, page data) and each new job''s own page for its description, politely: robots.txt allows them, one request a second. Rippling documents a Job Board API for showing a customer''s jobs on its own careers site; the pages carry the same data. Boards are found on the careers pages we read. Approved 2026-11-18 (Phase 0 review).'),
  ('dover_board', 'Dover job boards', 'restricted_site', 'restricted', 'https://jobs.dover.com/robots.txt', 'Not collected. Dover''s job pages are empty shells that load their jobs from /api/, which its robots.txt disallows. Phase 0 review, 2026-11-18.'),
  ('bamboohr_board', 'BambooHR careers sites', 'job_api', 'pending_review', NULL, 'Not collected yet. Each company''s careers site loads its jobs from {company}.bamboohr.com/careers/list (JSON; robots.txt allows it), but BambooHR does not document that feed; only third parties describe it, and they note it changes. Awaiting the product owner''s decision. Phase 0 review, 2026-11-18.')
